import asyncio
from typing import Callable, Awaitable


async def run_tasks(tasks: list[Callable[[], Awaitable[None]]], max_concurrent: int) -> None:
    """
    Run async tasks with a maximum concurrency limit.

    Handles keyboard interrupts gracefully, ensuring tasks' cleanup code
    (in try/finally blocks) runs even for tasks waiting on the semaphore.

    Args:
        tasks: List of async functions to run
        max_concurrent: Maximum number of tasks to run concurrently
    """
    semaphore = asyncio.Semaphore(max_concurrent)
    all_tasks: list[asyncio.Task] = []

    async def run_one(task_func: Callable[[], Awaitable[None]]) -> None:
        coro = task_func()  # Create coroutine immediately
        acquired = False
        try:
            # Cancellable semaphore acquisition
            while not acquired:
                try:
                    await asyncio.wait_for(semaphore.acquire(), timeout=0.01)
                    acquired = True
                except asyncio.TimeoutError:
                    pass

            await coro
        except asyncio.CancelledError:
            if not acquired:
                # Run the coroutine so its cleanup (finally blocks) executes
                # Use a task so we can control cancellation
                cleanup_task = asyncio.create_task(coro)
                try:
                    # Give cleanup a reasonable time to complete
                    await asyncio.wait_for(cleanup_task, timeout=5.0)
                except asyncio.TimeoutError:
                    cleanup_task.cancel()
                    try:
                        await cleanup_task
                    except asyncio.CancelledError:
                        pass
                except asyncio.CancelledError:
                    pass
            raise
        finally:
            if acquired:
                semaphore.release()

    try:
        all_tasks = [asyncio.create_task(run_one(task)) for task in tasks]
        await asyncio.gather(*all_tasks)
    except asyncio.CancelledError:
        # Wait for all tasks to handle their cleanup
        for task in all_tasks:
            if not task.done():
                try:
                    await task
                except asyncio.CancelledError:
                    pass
        raise
    finally:
        # Cancel any remaining tasks and let them clean up
        for task in all_tasks:
            if not task.done():
                task.cancel()

        if all_tasks:
            await asyncio.gather(*all_tasks, return_exceptions=True)
